import unittest

from solucao import colar
from solucao import limpar


class TestTirarOsEspacos(unittest.TestCase):
    def test_tira_espacos_dos_dois_lados(self):
        """limpar tira os espacos dos dois lados"""
        self.assertEqual(limpar("  ola  "), "ola")

    def test_espacos_do_meio_ficam(self):
        """limpar deixa os espacos do meio como estao"""
        self.assertEqual(limpar("o l a"), "o l a")

    def test_cola_os_dois_limpos(self):
        """colar cola os textos ja limpos com um espaco"""
        self.assertEqual(colar("  ana  ", "  souza  "), "ana souza")

    def test_cola_com_um_lado_sujo(self):
        """colar limpa cada lado antes de colar"""
        self.assertEqual(colar("ola", "mundo "), "ola mundo")

